#!/usr/bin/env bash
# .claude/hooks/generated-guard.sh — PreToolUse guard (Edit|Write|MultiEdit).
#
# Blocks edits to generated or vendored files before they happen. Exit 2
# refuses the edit (message on stderr); exit 0 lets it proceed. Paths are
# matched on suffix so this works regardless of checkout location.
#
#   1. syntaxes/musa.tmLanguage.json is generated by build/generate-grammar.js;
#      `npm run grammar:check` fails on hand edits.
#   2. dist/ and out/ are esbuild/test build output.
#   3. node_modules/ holds vendored npm dependencies.
set -euo pipefail

command -v jq >/dev/null 2>&1 || exit 0
input="$(cat)"
file="$(printf '%s' "$input" | jq -r '.tool_input.file_path // empty')"
[ -n "$file" ] || exit 0

case "$file" in
*/syntaxes/musa.tmLanguage.json)
	echo "Refusing to edit '$file': it is generated by build/generate-grammar.js. Edit the generator, then run 'npm run grammar'." >&2
	exit 2
	;;
*/dist/* | */out/*)
	echo "Refusing to edit '$file': esbuild build output. Rebuild with 'npm run compile'." >&2
	exit 2
	;;
*/node_modules/*)
	echo "Refusing to edit '$file': node_modules/ holds vendored npm dependencies." >&2
	exit 2
	;;
esac

exit 0
